import { readFile, writeFile, rm, mkdtemp } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { inspectMedia, analyzeMedia, exportMedia } from '../tests/reference/server/media.mjs';
import { DEFAULT_SETTINGS } from '../shared/timeline.mjs';
import { capture } from '../tests/reference/server/process.mjs';

// Reuses the deterministic 60-minute fixture generated by scripts/benchmark.mjs.
const directory = await mkdtemp(path.join(os.tmpdir(), 'hypercut-range-long-'));
try {
  const begin = performance.now();
  const media = await inspectMedia(path.resolve('test-output/benchmark/3600s.mp4'));
  const analysis = await analyzeMedia(media, DEFAULT_SETTINGS, media.audioTracks[0].index);
  const preparationSeconds = (performance.now() - begin) / 1000;
  assert.equal(analysis.cuts.length, 1000);
  const report = { status: 'PASS', scope: 'Synthetic 1080p30 60-minute input, 1000 cuts, selected original 3590–3599 seconds. Input/hash/frame-index/analysis preparation measured separately. Preview runs reuse the frame index and warm OS cache; not a full-app benchmark.', fingerprint: media.fingerprint, preparationSeconds, runs: [] };
  for (let iteration = 1; iteration <= 3; iteration++) {
    const start = performance.now();
    const output = await exportMedia(media, analysis.cuts, 1, directory, { preview: true, range: { start: 3590, end: 3599 } });
    const seconds = (performance.now() - start) / 1000;
    assert.ok(Math.abs(output.duration - 7.533333) < 0.034);
    const metadata = await capture('ffmpeg', ['-v', 'error', '-i', output.path, '-vf', 'signalstats,metadata=print:file=-', '-an', '-f', 'null', '-']);
    const flashes = []; let time = 0, white = false;
    for (const line of metadata.split('\n')) {
      const match = line.match(/pts_time:([\d.]+)/); if (match) time = Number(match[1]);
      if (line.startsWith('lavfi.signalstats.YAVG=')) { const next = Number(line.split('=')[1]) > 200; if (next && !white) flashes.push(time); white = next; }
    }
    const pcmPath = path.join(directory, 'decoded.f32');
    await capture('ffmpeg', ['-v', 'error', '-i', output.path, '-map', '0:a:0', '-f', 'f32le', '-ac', '1', '-ar', '48000', '-y', pcmPath]);
    const pcm = await readFile(pcmPath), tones = []; let active = false, last = -10000;
    for (let i = 0; i < pcm.length / 4; i++) {
      if (Math.abs(pcm.readFloatLE(i * 4)) > 0.07) { if (!active) tones.push(i / 48000); active = true; last = i; }
      else if (i - last > 2400) active = false;
    }
    assert.equal(flashes.length, 2); assert.equal(tones.length, 3);
    const expectedFlashes = [2.466667, 5.333333], expectedTones = [0, 2.066667, 4.933333];
    flashes.forEach((t, i) => assert.ok(Math.abs(t - expectedFlashes[i]) < 0.001, `flash ${t}`));
    tones.forEach((t, i) => assert.ok(Math.abs(t - expectedTones[i]) < 0.005, `tone ${t}`));
    const extraSyncError = flashes.map((t, i) => t - tones[i + 1] - 0.4);
    extraSyncError.forEach(error => assert.ok(Math.abs(error) < 0.005));
    report.runs.push({ iteration, seconds, previewSeconds: output.duration, audioSamples: output.audioSamples, flashes, tones, extraSyncError, verified: output.verified });
    await rm(output.path); console.log(JSON.stringify(report.runs.at(-1)));
  }
  await writeFile(path.resolve('test-output/range-preview-long.json'), JSON.stringify(report, null, 2));
} finally { await rm(directory, { recursive: true, force: true }); }
